"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[2572],{7654(e,r,n){n.r(r),n.d(r,{assets:()=>l,contentTitle:()=>o,default:()=>p,frontMatter:()=>i,metadata:()=>t,toc:()=>u});const t=JSON.parse('{"id":"camera2/what-can-modern-smartphone-cameras-do","title":"Chapitre 3 : La photographie moderne sur smartphone","description":"Un tour d\'horizon des fonctionnalit\xe9s computationnelles et optiques des t\xe9l\xe9phones modernes : HDR, portrait bokeh, nuit mode, ralenti, ultra-grand angle, t\xe9l\xe9objectif, macro, et comment la photographie computationnelle fusionne mat\xe9riel et logiciel.","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/camera2/what-can-modern-smartphone-cameras-do.md","sourceDirName":"camera2","slug":"/camera2/what-can-modern-smartphone-cameras-do","permalink":"/AndroidCameraParameters/fr/camera2/what-can-modern-smartphone-cameras-do","draft":false,"unlisted":false,"editUrl":"https://github.com/zoozooll/AndroidCameraParameters/tree/main/website/docs/camera2/what-can-modern-smartphone-cameras-do.md","tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3,"title":"Chapitre 3 : La photographie moderne sur smartphone","description":"Un tour d\'horizon des fonctionnalit\xe9s computationnelles et optiques des t\xe9l\xe9phones modernes : HDR, portrait bokeh, nuit mode, ralenti, ultra-grand angle, t\xe9l\xe9objectif, macro, et comment la photographie computationnelle fusionne mat\xe9riel et logiciel.","keywords":["photographie HDR","mode portrait","mode nuit","vid\xe9o au ralenti","cam\xe9ra ultra-grand angle","t\xe9l\xe9objectif","photographie computationnelle"]},"sidebar":"tutorialSidebar","previous":{"title":"Chapitre 2 : Comprendre les cam\xe9ras des smartphones","permalink":"/AndroidCameraParameters/fr/camera2/understanding-smartphone-cameras"},"next":{"title":"Chapitre 4 : Explorez votre propre t\xe9l\xe9phone","permalink":"/AndroidCameraParameters/fr/camera2/exploring-your-phones-camera"}}');var a=n(4848),s=n(8453);const i={sidebar_position:3,title:"Chapitre 3 : La photographie moderne sur smartphone",description:"Un tour d'horizon des fonctionnalit\xe9s computationnelles et optiques des t\xe9l\xe9phones modernes : HDR, portrait bokeh, nuit mode, ralenti, ultra-grand angle, t\xe9l\xe9objectif, macro, et comment la photographie computationnelle fusionne mat\xe9riel et logiciel.",keywords:["photographie HDR","mode portrait","mode nuit","vid\xe9o au ralenti","cam\xe9ra ultra-grand angle","t\xe9l\xe9objectif","photographie computationnelle"]},o="Chapitre 3 : La photographie moderne sur smartphone",l={},u=[{value:"HDR : Fusion multi-images \xe0 plage dynamique \xe9lev\xe9e",id:"hdr--fusion-multi-images-\xe0-plage-dynamique-\xe9lev\xe9e",level:2},{value:"Comment fonctionne le HDR sur smartphone",id:"comment-fonctionne-le-hdr-sur-smartphone",level:3},{value:"Quand le HDR fonctionne et quand il \xe9choue",id:"quand-le-hdr-fonctionne-et-quand-il-\xe9choue",level:3},{value:"Mode Portrait : Bokeh via l&#39;estimation de la profondeur",id:"mode-portrait--bokeh-via-lestimation-de-la-profondeur",level:2},{value:"Trois m\xe9thodes d&#39;estimation de la profondeur sur smartphone",id:"trois-m\xe9thodes-destimation-de-la-profondeur-sur-smartphone",level:3},{value:"Le pipeline de rendu de portrait",id:"le-pipeline-de-rendu-de-portrait",level:3},{value:"Mode Nuit : Fusion temporelle multi-images",id:"mode-nuit--fusion-temporelle-multi-images",level:2},{value:"L&#39;algorithme du mode nuit \xe9tape par \xe9tape",id:"lalgorithme-du-mode-nuit-\xe9tape-par-\xe9tape",level:3},{value:"Ralenti : Capture recadr\xe9e \xe0 fr\xe9quence d&#39;images \xe9lev\xe9e",id:"ralenti--capture-recadr\xe9e-\xe0-fr\xe9quence-dimages-\xe9lev\xe9e",level:2},{value:"Pourquoi le 960 fps n\xe9cessite un recadrage du capteur",id:"pourquoi-le-960-fps-n\xe9cessite-un-recadrage-du-capteur",level:3},{value:"Ultra-grand-angle : Correction de distorsion et qualit\xe9 des bords",id:"ultra-grand-angle--correction-de-distorsion-et-qualit\xe9-des-bords",level:2},{value:"T\xe9l\xe9objectif : Standard vs P\xe9riscope",id:"t\xe9l\xe9objectif--standard-vs-p\xe9riscope",level:2},{value:"Macro : Photographie de gros plan extr\xeame",id:"macro--photographie-de-gros-plan-extr\xeame",level:2},{value:"Photographie computationnelle : La philosophie unificatrice",id:"photographie-computationnelle--la-philosophie-unificatrice",level:2},{value:"R\xe9sum\xe9",id:"r\xe9sum\xe9",level:2},{value:"Et ensuite ?",id:"et-ensuite-",level:2}];function d(e){const r={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",mermaid:"mermaid",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(r.header,{children:(0,a.jsx)(r.h1,{id:"chapitre-3--la-photographie-moderne-sur-smartphone",children:"Chapitre 3 : La photographie moderne sur smartphone"})}),"\n",(0,a.jsxs)(r.p,{children:["Le chapitre 2 vous a donn\xe9 les bases mat\xe9rielles : objectifs, capteurs, pipelines ISP et modules multi-cam\xe9ras. Ce chapitre r\xe9pond \xe0 la question suivante : ",(0,a.jsx)(r.strong,{children:"Comment les applications cam\xe9ra modernes utilisent-elles r\xe9ellement ce mat\xe9riel pour produire les photos que je vois sur Instagram ?"})]}),"\n",(0,a.jsx)(r.p,{children:"Un smartphone de 2010 prenait une seule exposition, la passait dans un ISP basique et \xe9crivait un JPEG. Un smartphone de 2026 capture couramment de 5 \xe0 15 images distinctes pour une seule photo fixe, les aligne avec une pr\xe9cision de sous-pixel \xe0 l'aide des donn\xe9es du gyroscope, les fusionne par un traitement du signal multi-images, passe le r\xe9sultat dans un r\xe9seau neuronal pour la segmentation s\xe9mantique ou l'estimation de la profondeur, et enfin effectue un mappage de tons pour obtenir une image unique partageable \u2014 le tout en un seul appui sur le bouton d'obturateur."}),"\n",(0,a.jsx)(r.p,{children:"Ce chapitre est un tour d'horizon des fonctionnalit\xe9s de la photographie moderne sur smartphone. Nous expliquerons comment chaque fonctionnalit\xe9 fonctionne au niveau mat\xe9riel + logiciel, sans aucun code API Camera2. L'objectif est de construire un vocabulaire de ce que les syst\xe8mes de cam\xe9ra modernes peuvent faire, afin que lorsque vous \xe9crirez plus tard du code pour contr\xf4ler ces fonctionnalit\xe9s, vous sachiez ce qui se passe sous le capot."}),"\n",(0,a.jsx)(r.h2,{id:"hdr--fusion-multi-images-\xe0-plage-dynamique-\xe9lev\xe9e",children:"HDR : Fusion multi-images \xe0 plage dynamique \xe9lev\xe9e"}),"\n",(0,a.jsxs)(r.p,{children:["La ",(0,a.jsx)(r.strong,{children:"plage dynamique"})," (dynamic range) est le rapport entre les parties les plus claires et les plus sombres d'une sc\xe8ne qu'un syst\xe8me d'imagerie peut enregistrer simultan\xe9ment sans saturation. L'\u0153il humain peut percevoir environ 20 paliers de plage dynamique (un rapport de contraste de 1 000 000:1) d'un seul regard, gr\xe2ce \xe0 l'adaptation saccadique. Une seule exposition d'un capteur de smartphone peut capturer environ 10 \xe0 12 paliers \xe0 l'ISO de base. L'\xe9cart entre ces deux chiffres est la raison pour laquelle le HDR existe."]}),"\n",(0,a.jsx)(r.p,{children:"Imaginez que vous preniez une photo \xe0 l'int\xe9rieur avec une fen\xeatre lumineuse derri\xe8re votre sujet. Si vous exposez pour le visage de la personne (disons 1/30s, ISO 400), la fen\xeatre devient d'un blanc pur satur\xe9 \u2014 plus de ciel, plus de nuages, plus de d\xe9tails. Si vous exposez pour la fen\xeatre (1/2000s, ISO 50), le visage de la personne devient une silhouette noire. Aucune exposition unique ne fonctionne."}),"\n",(0,a.jsx)(r.h3,{id:"comment-fonctionne-le-hdr-sur-smartphone",children:"Comment fonctionne le HDR sur smartphone"}),"\n",(0,a.jsxs)(r.p,{children:["Chaque syst\xe8me HDR sur les t\xe9l\xe9phones modernes utilise le ",(0,a.jsx)(r.strong,{children:"bracketing multi-images"})," suivi d'une fusion computationnelle. L'algorithme fonctionne ainsi :"]}),"\n",(0,a.jsxs)(r.ol,{children:["\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Capture bracket\xe9e"})," : La cam\xe9ra capture une rafale rapide de 3 \xe0 10 images cons\xe9cutives \xe0 diff\xe9rentes valeurs d'exposition (EV). Un ensemble typique pourrait comprendre des images \xe0 -3 EV (tr\xe8s court, pr\xe9serve les hautes lumi\xe8res), -1 EV, +1 EV et +3 EV (tr\xe8s long, capte les ombres). Le capteur et le VCM sont maintenus parfaitement immobiles pendant la rafale ; seul le minutage de l'obturateur \xe9lectronique change."]}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"S\xe9lection de l'image de r\xe9f\xe9rence"})," : L'algorithme choisit l'image \xe0 exposition moyenne la plus nette comme r\xe9f\xe9rence g\xe9om\xe9trique."]}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Recalage / Alignement d'images"})," : Chaque image non-r\xe9f\xe9rente est align\xe9e math\xe9matiquement sur la r\xe9f\xe9rence. L'algorithme trouve des points caract\xe9ristiques distinctifs (coins, bords) \xe0 l'aide d'algorithmes comme FAST ou SIFT, calcule une transformation affine ou homographique qui mappe les caract\xe9ristiques de chaque image sur l'image de r\xe9f\xe9rence, et d\xe9forme les pixels en cons\xe9quence. Toutes les images trop floues (\xe0 cause d'un micro-tremblement pendant la rafale) sont purement et simplement rejet\xe9es."]}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Fusion"})," : Pour chaque emplacement de pixel dans l'image finale, l'algorithme combine les informations des images align\xe9es. Les pixels sous-expos\xe9s apportent leurs donn\xe9es de hautes lumi\xe8res nettes et non satur\xe9es. Les pixels surexpos\xe9s apportent leurs donn\xe9es d'ombres \xe0 faible bruit. Les pixels des tons moyens sont moyenn\xe9s sur toutes les images pour r\xe9duire le bruit de grenaille."]}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Mappage de tons (Tone mapping)"})," : L'image lin\xe9aire fusionn\xe9e \u2014 qui peut d\xe9sormais contenir 14 \xe0 18 paliers de plage dynamique utilisable \u2014 est compress\xe9e par un op\xe9rateur de mappage de tons local sophistiqu\xe9 en une image de sortie 8 bits ou 10 bits qui a fi\xe8re allure sur un \xe9cran sRVB standard."]}),"\n"]}),"\n",(0,a.jsx)(r.mermaid,{value:'flowchart LR\n    A["Sc\xe8ne : Fen\xeatre lumineuse + Pi\xe8ce sombre"] --\x3e B["Capture en rafale"]\n    B --\x3e C1["Image -3 EV<br/>Sombre, pr\xe9serve les hautes lumi\xe8res"]\n    B --\x3e C2["Image 0 EV<br/>R\xe9f\xe9rence d\'exposition moyenne"]\n    B --\x3e C3["Image +3 EV<br/>Lumineuse, pr\xe9serve les ombres"]\n    C1 --\x3e D["Recalage / Alignement<br/>Correspondance caract\xe9ristiques + D\xe9formation"]\n    C2 --\x3e D\n    C3 --\x3e D\n    D --\x3e E["Fusionner / M\xe9langer<br/>M\xe9lange d\'exposition par pixel"]\n    E --\x3e F["Mappage de tons local<br/>16 paliers vers affichage 8 bits"]\n    F --\x3e G["Sortie HDR finale<br/>Visage visible + Ciel d\xe9taill\xe9"]'}),"\n",(0,a.jsxs)(r.p,{children:['Exemple concret : un Galaxy S26 Ultra en mode "Optimiseur de sc\xe8ne HDR" par d\xe9faut d\xe9clenche en interne 7 images bracket\xe9es totalisant environ 0,2 seconde de temps de capture. La d\xe9tection de mouvement de la main int\xe9gr\xe9e rejette 2 images floues. Les 5 images restantes sont align\xe9es, fusionn\xe9es et mapp\xe9es en tons. La sortie est \xe9crite sous forme de ',(0,a.jsx)(r.strong,{children:"fichier JPEG_R Ultra HDR"})," sur les appareils Android 14+ : une image principale JPEG standard (8 bits SDR) avec une carte de gain int\xe9gr\xe9e que les visionneuses compatibles HDR (Galerie Android 14, Chrome 120+, Adobe Lightroom) peuvent utiliser pour reconstruire toute la plage de luminance HDR 10 bits sur un \xe9cran HDR10 ou Dolby Vision."]}),"\n",(0,a.jsx)(r.h3,{id:"quand-le-hdr-fonctionne-et-quand-il-\xe9choue",children:"Quand le HDR fonctionne et quand il \xe9choue"}),"\n",(0,a.jsx)(r.p,{children:"Le HDR excelle dans les sc\xe8nes statiques pr\xe9sentant \xe0 la fois des hautes lumi\xe8res vives et des ombres profondes : paysages, portraits \xe0 contre-jour, pi\xe8ces avec fen\xeatres, couchers de soleil sur l'eau. Il \xe9choue activement \u2014 produisant des artefacts fant\xf4mes \u2014 lorsque des objets dans la sc\xe8ne bougent pendant la rafale bracket\xe9e : un oiseau en vol, un drapeau qui flotte, une personne qui cligne des yeux, un enfant qui court. Les algorithmes HDR modernes aliment\xe9s par l'IA d\xe9tectent et segmentent les objets en mouvement, ne m\xe9langeant que l'image de r\xe9f\xe9rence pour ces pixels afin d'\xe9viter le classique \"fant\xf4me\" HDR."}),"\n",(0,a.jsx)(r.h2,{id:"mode-portrait--bokeh-via-lestimation-de-la-profondeur",children:"Mode Portrait : Bokeh via l'estimation de la profondeur"}),"\n",(0,a.jsxs)(r.p,{children:["Le mode portrait produit une esth\xe9tique o\xf9 le visage du sujet est parfaitement net et l'arri\xe8re-plan se dissout dans un flou cr\xe9meux appel\xe9 ",(0,a.jsx)(r.strong,{children:"bokeh"}),". Les appareils photo traditionnels y parviennent optiquement avec de grands capteurs, de larges ouvertures et de longues distances focales. Les smartphones y parviennent par le calcul, car un capteur 1/1,3 pouce \xe0 f/1,6 ne produit pas naturellement une profondeur de champ assez faible pour cet effet."]}),"\n",(0,a.jsx)(r.h3,{id:"trois-m\xe9thodes-destimation-de-la-profondeur-sur-smartphone",children:"Trois m\xe9thodes d'estimation de la profondeur sur smartphone"}),"\n",(0,a.jsx)(r.p,{children:"Il existe trois techniques ind\xe9pendantes utilis\xe9es par les syst\xe8mes de portrait modernes ; de nombreux t\xe9l\xe9phones utilisent une combinaison des trois."}),"\n",(0,a.jsxs)(r.p,{children:[(0,a.jsx)(r.strong,{children:"M\xe9thode 1 : Disparit\xe9 st\xe9r\xe9o \xe0 partir de deux cam\xe9ras."})," C'est la m\xe9thode la plus ancienne et la plus solide g\xe9om\xe9triquement. Le t\xe9l\xe9phone d\xe9clenche simultan\xe9ment la cam\xe9ra grand-angle et la cam\xe9ra t\xe9l\xe9objectif sur le m\xeame sujet. Comme les deux cam\xe9ras sont physiquement s\xe9par\xe9es de 10 \xe0 15 millim\xe8tres (la \"ligne de base\"), elles voient le sujet depuis des positions horizontales l\xe9g\xe8rement diff\xe9rentes. La position d'un objet au premier plan se d\xe9place davantage entre les deux points de vue que celle d'un objet lointain \xe0 l'arri\xe8re-plan. Ce d\xe9calage est appel\xe9 ",(0,a.jsx)(r.strong,{children:"disparit\xe9"}),". L'algorithme ex\xe9cute une mise en correspondance de blocs ou un algorithme de correspondance semi-globale (SGM) sur les deux images rectifi\xe9es pour calculer une valeur de disparit\xe9 pour chaque pixel. La disparit\xe9 est inversement proportionnelle \xe0 la profondeur, donc la carte de disparit\xe9 est convertie directement en une carte de profondeur par pixel."]}),"\n",(0,a.jsxs)(r.p,{children:[(0,a.jsx)(r.strong,{children:"M\xe9thode 2 : D\xe9tection active de la profondeur ToF / LiDAR."})," Un capteur de profondeur ToF (Time-of-Flight) ou LiDAR projette un motif structur\xe9 de plus de 30 000 points laser proche infrarouge sur la sc\xe8ne, puis mesure le temps de trajet aller-retour (pour le ToF direct) ou le d\xe9phasage (pour le ToF indirect) de la lumi\xe8re r\xe9fl\xe9chie pour calculer une profondeur m\xe9trique r\xe9elle en m\xe8tres pour chaque pixel. Le ToF produit des cartes de profondeur denses et pr\xe9cises m\xeame dans l'obscurit\xe9 totale et sur des surfaces sans texture (murs unis, ciel) o\xf9 la correspondance st\xe9r\xe9o \xe9choue. Les syst\xe8mes de portrait modernes utilisent g\xe9n\xe9ralement le ToF comme signal de profondeur de r\xe9f\xe9rence et la disparit\xe9 st\xe9r\xe9o comme signal de raffinement."]}),"\n",(0,a.jsxs)(r.p,{children:[(0,a.jsx)(r.strong,{children:"M\xe9thode 3 : Estimation de la profondeur ML monoculaire."})," Pour les t\xe9l\xe9phones \xe0 cam\xe9ra unique (ou pour la cam\xe9ra selfie frontale, qui n'a pas de partenaire st\xe9r\xe9o), un r\xe9seau neuronal estime la profondeur \xe0 partir d'une seule image RVB. Le mod\xe8le, entra\xeen\xe9 sur des millions d'images avec des \xe9tiquettes de profondeur de r\xe9f\xe9rence, apprend les indices statistiques que les humains utilisent pour juger de la profondeur : taille relative, occlusion, perspective lin\xe9aire, gradient de texture, flou de d\xe9focalisation et perspective atmosph\xe9rique. PortraitNet de Google et DeepLabV3+ de Meta sont des architectures repr\xe9sentatives. La profondeur monoculaire est moins pr\xe9cise m\xe9triquement que la st\xe9r\xe9o ou le ToF, mais elle est suffisante pour un bokeh de portrait \xe0 l'aspect plausible."]}),"\n",(0,a.jsx)(r.h3,{id:"le-pipeline-de-rendu-de-portrait",children:"Le pipeline de rendu de portrait"}),"\n",(0,a.jsx)(r.p,{children:"Une fois qu'une carte de profondeur est obtenue, les \xe9tapes restantes sont les m\xeames, quelle que soit la m\xe9thode d'estimation de la profondeur utilis\xe9e :"}),"\n",(0,a.jsxs)(r.ol,{children:["\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Segmentation du sujet"}),' : Un r\xe9seau neuronal de segmentation s\xe9mantique distinct (g\xe9n\xe9ralement une variante U-Net) s\'ex\xe9cute sur l\'image RVB de la cam\xe9ra principale et produit un masque alpha progressif identifiant les pixels appartenant \xe0 la "personne" par rapport \xe0 l\'"arri\xe8re-plan". Le masque est adouci sur les bords \u2014 particuli\xe8rement autour des cheveux, des lunettes et des d\xe9tails fins du premier plan \u2014 pour \xe9viter l\'aspect "poup\xe9e de papier" d\xe9coup\xe9e des d\xe9buts du mode portrait en 2010.']}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Raffinement de la profondeur"})," : La carte de profondeur brute issue de la m\xe9thode 1/2/3 est multipli\xe9e par le masque de segmentation. Les pixels d'arri\xe8re-plan conservent leur valeur de profondeur ; les pixels du sujet sont bloqu\xe9s sur une profondeur de plan de mise au point unique."]}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Flou variable par pixel"})," : Chaque pixel d'arri\xe8re-plan est flout\xe9 par un noyau gaussien (ou, pour les modes \"simulation optique\" haut de gamme, une convolution de noyau d'objectif rendu physiquement) dont le rayon varie lin\xe9airement avec la distance du pixel par rapport au plan de mise au point. Un objet d'arri\xe8re-plan \xe0 5 m\xe8tres re\xe7oit un flou important ; un objet d'arri\xe8re-plan \xe0 1,5 m\xe8tre re\xe7oit un flou l\xe9ger. Les pixels du sujet sont copi\xe9s sans modification."]}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Reflets optiques simul\xe9s"})," : Une touche premium : les reflets sp\xe9culaires brillants dans l'arri\xe8re-plan flou (lampadaires, reflets, soleil) sont rendus sous forme d'hexagones ou de cercles de bokeh caract\xe9ristiques de la forme d'un objectif, plut\xf4t que de simples taches gaussiennes. Cela renforce l'illusion que le flou provient d'un v\xe9ritable diaphragme d'objectif."]}),"\n"]}),"\n",(0,a.jsx)(r.mermaid,{value:'flowchart TD\n    A["Image cam\xe9ra grand-angle + Image t\xe9l\xe9objectif / Donn\xe9es ToF"] --\x3e B["Estimation de la profondeur<br/>St\xe9r\xe9o / ToF / ML Mono"]\n    B --\x3e C["Carte de profondeur<br/>0,5m \xe0 l\'infini"]\n    A --\x3e D["Segmentation du sujet<br/>R\xe9seau neuronal U-Net"]\n    D --\x3e E["Masque alpha de la personne<br/>Adoucissement des bords"]\n    C --\x3e F["Rayon de flou par pixel<br/>Varie selon la profondeur"]\n    E --\x3e F\n    F --\x3e G["Appliquer le flou variable<br/>Sujet = Net, Arri\xe8re-plan = Bokeh"]\n    G --\x3e H["Ajouter les reflets bokeh<br/>Hexagonaux / Circulaires"]\n    H --\x3e I["Photo de portrait finale<br/>Flou d\'arri\xe8re-plan cr\xe9meux"]'}),"\n",(0,a.jsx)(r.h2,{id:"mode-nuit--fusion-temporelle-multi-images",children:"Mode Nuit : Fusion temporelle multi-images"}),"\n",(0,a.jsxs)(r.p,{children:["Avant 2018, la photographie sur smartphone en basse lumi\xe8re \xe9tait essentiellement inutilisable sans flash. Un bar sombre ou une rue de ville la nuit produisait un fouillis bruyant, granuleux et flou. Puis Google a sorti ",(0,a.jsx)(r.strong,{children:"Night Sight"})," sur le Pixel 3, et tout a chang\xe9. L'id\xe9e centrale \xe9tait contre-intuitive : au lieu de prendre une seule longue exposition d'une seconde (qui serait d\xe9sesp\xe9r\xe9ment floue \xe0 cause du tremblement de la main), prenez 15 expositions tr\xe8s courtes de 1/15e de seconde (chacune individuellement nette parce que l'OIS est actif), puis alignez-les et faites-en la moyenne par algorithme. Le temps d'exposition total int\xe9gr\xe9 est toujours d'une seconde, mais l'exposition par image est assez courte pour que le flou de boug\xe9 ne s'accumule jamais."]}),"\n",(0,a.jsx)(r.h3,{id:"lalgorithme-du-mode-nuit-\xe9tape-par-\xe9tape",children:"L'algorithme du mode nuit \xe9tape par \xe9tape"}),"\n",(0,a.jsxs)(r.ol,{children:["\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Capture en rafale"})," : La cam\xe9ra capture 8 \xe0 15 images RAW. Chaque image utilise un temps d'exposition mod\xe9r\xe9 (1/15s \xe0 1/8s est typique) et un ISO mod\xe9r\xe9 (800 \xe0 3200). Les images individuelles sont bruit\xe9es mais pas floues. La rafale dure de 0,5 \xe0 2 secondes en temps r\xe9el."]}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Alignement EIS assist\xe9 par gyro"})," : Le gyroscope de l'IMU principal du t\xe9l\xe9phone enregistre la vitesse angulaire \xe0 8 000 Hz pendant toute la rafale. Pour chaque image, la rotation et la translation cumul\xe9es par rapport \xe0 l'image de r\xe9f\xe9rence sont calcul\xe9es. Chaque image RAW est ensuite d\xe9cal\xe9e, pivot\xe9e et l\xe9g\xe8rement redimensionn\xe9e num\xe9riquement (Stabilisation d'image \xe9lectronique, EIS) sur le NPU \xe0 une pr\xe9cision de sous-pixel, la recalant parfaitement sur l'image de r\xe9f\xe9rence m\xeame si les mains de l'utilisateur ont boug\xe9 de plusieurs pixels pendant la rafale."]}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Fusion temporelle des pixels"})," : Pour chaque emplacement de pixel sur les 12 images align\xe9es, l'algorithme rassemble 12 valeurs de pixels candidates. Il effectue ensuite une fusion statistique robuste plut\xf4t qu'une simple moyenne : les valeurs aberrantes (caus\xe9es par des pixels chauds, des rayons cosmiques ou les phares d'une voiture passant \xe0 cet endroit) sont identifi\xe9es et rejet\xe9es. Les valeurs coh\xe9rentes restantes sont moyenn\xe9es, r\xe9duisant le bruit de grenaille gaussien par un facteur \xe9gal \xe0 la racine carr\xe9e du nombre d'images conserv\xe9es. Une fusion de 12 images r\xe9duit le bruit de 3,5\xd7."]}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"D\xe9bruitage spatial"})," : Un d\xe9bruiteur bas\xe9 sur un CNN (entra\xeen\xe9 sp\xe9cifiquement sur des images de nuit brutes) supprime tout bruit haute fr\xe9quence restant tout en pr\xe9servant les bords r\xe9els et la texture."]}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Mappage de tons local"})," : L'image RAW fusionn\xe9e a une plage dynamique tr\xe8s \xe9lev\xe9e. Un op\xe9rateur de mappage de tons variant dans l'espace (bas\xe9 sur un filtrage bilat\xe9ral ou un mappage de tons CNN appris) rehausse les ombres sans br\xfbler les lumi\xe8res de la ville, booste la saturation des couleurs dans les r\xe9gions sombres (qui sembleraient autrement d\xe9satur\xe9es) et produit une image 8 bits finale qui semble lumineuse et propre plut\xf4t que sombre et trouble."]}),"\n"]}),"\n",(0,a.jsx)(r.mermaid,{value:'flowchart LR\n    A["Sc\xe8ne sombre : Rue de ville la nuit"] --\x3e B["Capturer 12 images RAW<br/>1/15s chacune = 0,66s total"]\n    B --\x3e C["Alignement EIS gyro<br/>D\xe9calage sous-pixel + Rotation"]\n    C --\x3e D["Fusion temporelle<br/>Moyenne robuste / Rejet aberrants<br/>Bruit -3,5x"]\n    D --\x3e E["D\xe9bruiteur spatial CNN<br/>Pr\xe9serve bords / texture"]\n    E --\x3e F["Mappage de tons local<br/>Booste ombres / Pr\xe9serve lumi\xe8res"]\n    F --\x3e G["Photo de nuit nette et claire<br/>Faible bruit, pas de flou"]'}),"\n",(0,a.jsx)(r.p,{children:'Le "Nightography" de Samsung, le "Mode Nuit" d\'Apple, le "Night Mode 2.0" de Xiaomi et le "Ultra Dark Mode" d\'OPPO utilisent tous substantiellement la m\xeame architecture algorithmique. Des variations existent dans le nombre exact d\'images, le choix de la statistique de fusion robuste, l\'architecture du d\xe9bruiteur et l\'aspect du mappage de tons, mais la moyenne temporelle multi-images align\xe9e par gyroscope est universelle dans toute l\'industrie.'}),"\n",(0,a.jsx)(r.h2,{id:"ralenti--capture-recadr\xe9e-\xe0-fr\xe9quence-dimages-\xe9lev\xe9e",children:"Ralenti : Capture recadr\xe9e \xe0 fr\xe9quence d'images \xe9lev\xe9e"}),"\n",(0,a.jsx)(r.p,{children:"La vid\xe9o au ralenti \xe9tire le temps en capturant des images vid\xe9o plus rapidement que la fr\xe9quence de lecture standard de 30 fps, puis en les lisant \xe0 la vitesse normale de 30 fps. Les multiplicateurs courants :"}),"\n",(0,a.jsxs)(r.ul,{children:["\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Capture 120 fps \u2192 Lecture 30 fps = ralenti 4\xd7."})," Un \xe9v\xe9nement r\xe9el d'une seconde devient 4 secondes de vid\xe9o."]}),"\n",(0,a.jsx)(r.li,{children:(0,a.jsx)(r.strong,{children:"240 fps \u2192 30 fps = ralenti 8\xd7."})}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"960 fps \u2192 30 fps = ralenti ultra-fluide 32\xd7."})," Une \xe9claboussure de goutte d'eau, l'\xe9clatement d'un ballon ou le battement d'ailes d'un colibri deviennent visibles."]}),"\n"]}),"\n",(0,a.jsx)(r.h3,{id:"pourquoi-le-960-fps-n\xe9cessite-un-recadrage-du-capteur",children:"Pourquoi le 960 fps n\xe9cessite un recadrage du capteur"}),"\n",(0,a.jsxs)(r.p,{children:["Le goulot d'\xe9tranglement pour la capture \xe0 haute fr\xe9quence d'images est la ",(0,a.jsx)(r.strong,{children:"bande passante de lecture du capteur"}),". Le capteur d'image poss\xe8de un nombre fini de voies MIPI CSI-2 fonctionnant \xe0 un d\xe9bit de donn\xe9es maximal fixe (g\xe9n\xe9ralement 2,5 Gbps par voie, 4 voies = 10 Gbps au total). Le capteur ne peut sortir qu'un certain nombre de pixels par seconde."]}),"\n",(0,a.jsxs)(r.ul,{children:["\n",(0,a.jsx)(r.li,{children:"Une lecture d'image compl\xe8te de 48 MP (8000\xd76000) \xe0 960 fps n\xe9cessiterait 48 000 000 \xd7 960 = 46,08 milliards de pixels par seconde. C'est 30\xd7 la bande passante de lecture r\xe9elle de n'importe quel capteur de smartphone de 2026."}),"\n",(0,a.jsx)(r.li,{children:"Par cons\xe9quent, pour atteindre 960 fps, le capteur ne doit lire qu'un petit recadrage central de sa matrice de pixels. Un mode 960 fps est g\xe9n\xe9ralement un recadrage 1280\xd7720 (HD 720p) ou parfois 1920\xd71080 (FHD 1080p). La bande passante totale des pixels devient g\xe9rable : 1280\xd7720\xd7960 fps = 884 m\xe9gapixels par seconde, ce qui rentre confortablement dans les 10 Gbps m\xeame avec un codage 10 bits par pixel."}),"\n"]}),"\n",(0,a.jsx)(r.p,{children:"Les chiffres en pratique : capture 960 fps \xd7 0,3 seconde de temps r\xe9el = 288 images individuelles. Lu \xe0 30 fps = 9,6 secondes de vid\xe9o au ralenti fluide. Certains t\xe9l\xe9phones fleurons Sony Xperia et Samsung Galaxy prennent en charge une br\xe8ve rafale de 960 fps \xe0 une r\xe9solution 1080p en lisant le capteur via une banque de convertisseurs analogique-num\xe9rique (ADC) limit\xe9e uniquement dans la r\xe9gion de recadrage centrale."}),"\n",(0,a.jsx)(r.mermaid,{value:'flowchart TD\n    subgraph "Goulot d\'\xe9tranglement : Lecture du capteur"\n        direction TB\n        A["Mode capteur complet<br/>48 MP (8000x6000) @ 30fps<br/>= 1,44 GPix/s<br/>Photo / Vid\xe9o standard"]\n        B["Mode recadrage ralenti<br/>1280x720 @ 960fps<br/>= 0,88 GPix/s<br/>Ralenti ultra 32x"]\n    end\n    A --\x3e C{"Bus MIPI CSI-2<br/>4 voies x 2,5 Gbps<br/>= 10 Gbps total"}\n    B --\x3e C\n    C --\x3e D["Pipeline vid\xe9o ISP<br/>Redimensionne vers r\xe9solution sortie"]\n    D --\x3e E["Encodeur HEVC / AV1<br/>\xc9crit le MP4 au ralenti"]'}),"\n",(0,a.jsx)(r.p,{children:"Les modes de ralenti utilisent \xe9galement souvent une technique HDR d\xe9cal\xe9e o\xf9 des lignes altern\xe9es du capteur sont expos\xe9es pendant des dur\xe9es diff\xe9rentes pour maintenir une plage dynamique \xe9lev\xe9e, m\xeame \xe0 240 fps ou 960 fps."}),"\n",(0,a.jsx)(r.h2,{id:"ultra-grand-angle--correction-de-distorsion-et-qualit\xe9-des-bords",children:"Ultra-grand-angle : Correction de distorsion et qualit\xe9 des bords"}),"\n",(0,a.jsx)(r.p,{children:"La cam\xe9ra ultra-grand-angle d'un fleuron moderne offre une distance focale \xe9quivalente plein format de 10 \xe0 18 mm et un champ de vision diagonal de 100\xb0 \xe0 130\xb0. Elle ouvre des possibilit\xe9s de composition que la cam\xe9ra grand-angle standard ne permet pas : paysages vastes, photos d'architecture imposantes o\xf9 tout le b\xe2timent entre sans avoir \xe0 reculer dans le trafic, selfies de groupe qui incluent r\xe9ellement tout le monde, et un effet ludique de \"distorsion de proximit\xe9\" o\xf9 les objets tenus pr\xe8s de l'objectif apparaissent massivement surdimensionn\xe9s par rapport \xe0 l'arri\xe8re-plan."}),"\n",(0,a.jsx)(r.p,{children:"Cependant, la distance focale ultra-large s'accompagne de trois d\xe9fauts optiques caract\xe9ristiques que l'ISP doit corriger avant que la photo ne soit utilisable :"}),"\n",(0,a.jsxs)(r.ol,{children:["\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Distorsion g\xe9om\xe9trique (en barillet)"})," : Les lignes droites se courbent vers l'ext\xe9rieur comme les bords d'un objectif fisheye. Une photo d'un cadre de porte rectangulaire para\xeetra bomb\xe9e. L'\xe9tape de correction de la distorsion g\xe9om\xe9trique de l'ISP (voir chapitre 2) applique un remappage des coordonn\xe9es par pixel \xe0 l'aide d'un mod\xe8le d'objectif polynomial de 4e ou 6e ordre calibr\xe9 pour ce module sp\xe9cifique. La correction recadre n\xe9cessairement les 5 \xe0 10 % ext\xe9rieurs de la matrice du capteur car le remappage pousse ces pixels ext\xe9rieurs hors du cadre."]}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Aberration chromatique lat\xe9rale (LCA)"})," : L'objectif courbe les diff\xe9rentes longueurs d'onde de la lumi\xe8re par des quantit\xe9s l\xe9g\xe8rement diff\xe9rentes, de sorte que les images rouge, verte et bleue d'un m\xeame point hors axe atterrissent \xe0 des coordonn\xe9es de pixels l\xe9g\xe8rement diff\xe9rentes. Le r\xe9sultat est une frange de couleur visible (bords violets/verts) sur les objets \xe0 fort contraste pr\xe8s des coins. L'ISP corrige la LCA en appliquant un facteur de grossissement l\xe9g\xe8rement diff\xe9rent aux plans de couleur rouge et bleu par rapport au vert."]}),"\n",(0,a.jsxs)(r.li,{children:[(0,a.jsx)(r.strong,{children:"Vignettage / Flou dans les coins"})," : Les pixels des coins re\xe7oivent nettement moins de lumi\xe8re que les pixels du centre (en raison de la chute naturelle en cos\u2074\u03b8 de l'objectif et du vignettage m\xe9canique du barillet de l'objectif), et la fonction de transfert de modulation (MTF) optique de l'objectif est plus faible aux angles extr\xeames, ce qui rend les coins flous. L'\xe9tape de correction de l'ombrage de l'objectif applique un boost de gain \xe0 sym\xe9trie radiale pour aplatir l'\xe9clairage, et un filtre d'accentuation de la nettet\xe9 sensible aux contours est appliqu\xe9 plus agressivement aux coins qu'au centre."]}),"\n"]}),"\n",(0,a.jsx)(r.mermaid,{value:'flowchart LR\n    A["Capture ultra-large brute<br/>Fisheye 120 deg<br/>Distorsion barillet"] --\x3e B["Correction g\xe9om\xe9trique ISP<br/>Remappage polynomial 6e ordre"]\n    B --\x3e C["Sortie rectiligne recadr\xe9e<br/>Lignes r\xe9ellement droites"]\n    C --\x3e D["Correction LCA lat\xe9rale<br/>Redimensionnement plans R/B"]\n    D --\x3e E["Ombrage objectif + Nettet\xe9 coins"]\n    E --\x3e F["Photo ultra-large corrig\xe9e finale"]'}),"\n",(0,a.jsx)(r.h2,{id:"t\xe9l\xe9objectif--standard-vs-p\xe9riscope",children:"T\xe9l\xe9objectif : Standard vs P\xe9riscope"}),"\n",(0,a.jsx)(r.p,{children:"Le t\xe9l\xe9objectif capture les sujets \xe9loign\xe9s que la cam\xe9ra grand-angle ne peut pas r\xe9soudre. Les t\xe9l\xe9phones modernes proposent deux conceptions de t\xe9l\xe9objectif distinctes."}),"\n",(0,a.jsxs)(r.p,{children:[(0,a.jsx)(r.strong,{children:"T\xe9l\xe9objectif standard (optique 2\xd7 \xe0 3\xd7) :"})," Il s'agit d'un module cam\xe9ra conventionnel : le barillet de l'objectif est perpendiculaire au capot arri\xe8re du t\xe9l\xe9phone, directement au-dessus du capteur d'image, exactement comme la cam\xe9ra grand-angle mais avec un objectif \xe0 distance focale plus longue. Un t\xe9l\xe9objectif 3\xd7 a une distance focale \xe9quivalente plein format de ~72 mm. L'empilement physique est limit\xe9 par l'\xe9paisseur du t\xe9l\xe9phone (7\u20139 mm), donc l'objectif ne peut pas \xeatre plus long que cela. D'o\xf9 le plafond pratique de 3\xd7 pour les modules t\xe9l\xe9objectifs conventionnels."]}),"\n",(0,a.jsxs)(r.p,{children:[(0,a.jsx)(r.strong,{children:"T\xe9l\xe9objectif p\xe9riscope (optique 5\xd7 \xe0 10\xd7) :"})," Pour obtenir des distances focales plus longues sans \xe9paissir le t\xe9l\xe9phone, les ing\xe9nieurs ont pli\xe9 le chemin optique \xe0 90\xb0 \xe0 l'aide d'un prisme. La lumi\xe8re entre par une fen\xeatre sur le bord du t\xe9l\xe9phone ou sur la vitre arri\xe8re, frappe un prisme \xe0 angle droit de 45\xb0, rebondit \xe0 90\xb0 sur le c\xf4t\xe9, puis voyage horizontalement \xe0 travers un barillet d'objectif \xe0 plusieurs \xe9l\xe9ments de 10 \xe0 14 mm de long qui court parall\xe8lement \xe0 la carte m\xe8re du t\xe9l\xe9phone, pour finalement atterrir sur un capteur d'image mont\xe9 lat\xe9ralement sur le PCB. Le prisme lui-m\xeame est mont\xe9 sur un cardan OIS \xe0 2 axes, et le capteur est parfois mont\xe9 sur un OIS \xe0 d\xe9calage de capteur s\xe9par\xe9, offrant une stabilisation totale sur 4 ou 5 axes \u2014 suffisante pour obtenir des photos nettes \xe0 main lev\xe9e \xe0 10\xd7 du texte sur un panneau d'immeuble \xe9loign\xe9."]}),"\n",(0,a.jsx)(r.mermaid,{value:'graph LR\n    subgraph "T\xe9l\xe9objectif p\xe9riscope (vue de c\xf4t\xe9 interne)"\n        direction LR\n        A["Entr\xe9e lumi\xe8re<br/>Fen\xeatre vitre arri\xe8re"] --\x3e B["Prisme 45 deg<br/>R\xe9flexion 90 deg"]\n        B --\x3e C["\xc9l\xe9ment objectif 1"]\n        C --\x3e D["\xc9l\xe9ment objectif 2"]\n        D --\x3e E["\xc9l\xe9ment objectif 3"]\n        E --\x3e F["\xc9l\xe9ment objectif 4"]\n        F --\x3e G["\xc9l\xe9ment objectif 5"]\n        G --\x3e H["Filtre anti-IR"]\n        H --\x3e I["Capteur d\'image<br/>Mont\xe9 horizontalement"]\n    end\n    J["\xc9paisseur t\xe9l\xe9phone : 8,5 mm total"] --\x3e B'}),"\n",(0,a.jsx)(r.p,{children:'Aux limites de zoom entre les cam\xe9ras physiques (par exemple, 2,9\xd7 toujours recadr\xe9 num\xe9riquement de la cam\xe9ra grand-angle vs 3,1\xd7 utilisant le capteur t\xe9l\xe9objectif p\xe9riscope 3\xd7 natif), le HAL effectue un tour de fusion multi-cam\xe9ra : pour environ \xb10,2\xd7 autour du point de basculement, il capture les deux cam\xe9ras simultan\xe9ment et effectue un fondu encha\xeen\xe9 pond\xe9r\xe9 par le rapport de zoom, de sorte que l\'utilisateur ne voit jamais de "saut" visible lorsque la cam\xe9ra physique active change.'}),"\n",(0,a.jsx)(r.h2,{id:"macro--photographie-de-gros-plan-extr\xeame",children:"Macro : Photographie de gros plan extr\xeame"}),"\n",(0,a.jsx)(r.p,{children:"La photographie macro capture des gros plans extr\xeames de petits sujets : la texture des p\xe9tales de fleurs, les yeux compos\xe9s des insectes, les fibres d'un morceau de tissu, les cristaux de sucre individuels sur un biscuit."}),"\n",(0,a.jsx)(r.p,{children:"Deux strat\xe9gies macro existent dans les t\xe9l\xe9phones modernes :"}),"\n",(0,a.jsxs)(r.p,{children:[(0,a.jsx)(r.strong,{children:"Cam\xe9ra macro d\xe9di\xe9e :"})," Les t\xe9l\xe9phones d'entr\xe9e et de milieu de gamme sont souvent \xe9quip\xe9s d'un petit module macro d\xe9di\xe9 \xe0 basse r\xe9solution (2 MP \xe0 5 MP) avec un objectif \xe0 distance focale courte et mise au point fixe. Le module est r\xe9gl\xe9 pour une distance de mise au point minimale sp\xe9cifique (g\xe9n\xe9ralement 2\u20134 cm) et produit des images macro \xe9tonnamment nettes malgr\xe9 sa faible r\xe9solution. Le principal inconv\xe9nient est que le capteur est minuscule, de sorte que la qualit\xe9 de l'image se d\xe9grade fortement d\xe8s que la lumi\xe8re du jour n'est plus \xe9clatante."]}),"\n",(0,a.jsxs)(r.p,{children:[(0,a.jsx)(r.strong,{children:"Ultra-grand-angle r\xe9utilis\xe9 en macro :"})," Les t\xe9l\xe9phones fleurons (Google Pixel, Samsung s\xe9rie S Ultra, iPhone Pro) ne sont pas \xe9quip\xe9s d'une cam\xe9ra macro d\xe9di\xe9e. Au lieu de cela, ils r\xe9utilisent la cam\xe9ra ultra-grand-angle. La courte distance focale de l'ultra-grand-angle (13 mm \xe9q) lui conf\xe8re une distance de mise au point minimale tr\xe8s courte \u2014 souvent 1 \xe0 2 centim\xe8tres du sujet. Lorsque l'utilisateur appuie sur le mode \"Macro\" ou que l'application cam\xe9ra d\xe9tecte un sujet proche via le capteur ToF ou le t\xe9l\xe9m\xe8tre AF \xe0 d\xe9tection de phase, l'application passe \xe0 l'ultra-grand-angle, r\xe8gle son VCM sur la position de mise au point minimale, applique une correction de distorsion g\xe9om\xe9trique suppl\xe9mentaire (car le sujet se trouve maintenant \xe0 un extr\xeame de courbure de champ o\xf9 le remappage polynomial diff\xe8re consid\xe9rablement de la calibration \xe0 l'infini) et recadre le centre du capteur ultra-grand-angle pour produire l'image macro finale. Le grand capteur ultra-large de 12 MP \xe0 50 MP offre une qualit\xe9 d'image macro nettement sup\xe9rieure \xe0 celle d'un module d\xe9di\xe9 de 5 MP."]}),"\n",(0,a.jsx)(r.h2,{id:"photographie-computationnelle--la-philosophie-unificatrice",children:"Photographie computationnelle : La philosophie unificatrice"}),"\n",(0,a.jsxs)(r.p,{children:["Les fonctionnalit\xe9s ci-dessus \u2014 HDR, Portrait, Mode Nuit, Ralenti, correction Ultra-large, fusion de zoom P\xe9riscope, Macro \u2014 partagent une seule id\xe9e unificatrice. La ",(0,a.jsx)(r.strong,{children:"photographie computationnelle"})," est la philosophie selon laquelle le capteur de la cam\xe9ra, l'ISP, le gyroscope/IMU, le NPU (Neural Processing Unit) et les algorithmes de traitement du signal multi-images peuvent travailler ensemble pour produire des images qu'aucune combinaison objectif/capteur unique, aussi co\xfbteux soit le verre, ne pourrait jamais produire seule."]}),"\n",(0,a.jsx)(r.p,{children:"Le mod\xe8le reflex classique est : lumi\xe8re \u2192 objectif \u2192 capteur \u2192 stockage. Le mod\xe8le smartphone est : lumi\xe8re \u2192 objectifs multiples \u2192 capteurs multiples \u2192 gyro/IMU \u2192 capture de rafale multi-images \u2192 inf\xe9rence neurale NPU \u2192 fusion de d\xe9cision par pixel \u2192 mappage de tons sophistiqu\xe9 \u2192 stockage. Les deux commencent et finissent au m\xeame endroit, mais le smartphone ins\xe8re des dizaines d'\xe9tapes de calcul suppl\xe9mentaires au milieu, chacune am\xe9liorant le r\xe9sultat final d'une mani\xe8re que l'optique seule ne peut pas faire."}),"\n",(0,a.jsx)(r.p,{children:"Zoomer de mani\xe8re fluide de 0,5\xd7 \xe0 10\xd7 sur un Galaxy S26 Ultra est computationnel : le HAL m\xe9lange trois cam\xe9ras diff\xe9rentes avec trois distances focales diff\xe9rentes \xe0 travers cinq points de basculement de zoom. Sauver un portrait \xe0 contre-jour o\xf9 la fen\xeatre derri\xe8re le sujet n'est plus br\xfbl\xe9e est computationnel : fusion HDR \xe0 7 images. Une photo de nuit \xe0 main lev\xe9e de la Voie lact\xe9e qui n\xe9cessiterait un tr\xe9pied et une exposition de 30 secondes sur un reflex num\xe9rique est computationnelle : fusion temporelle de 12 images align\xe9es par gyroscope. Chaque fonctionnalit\xe9 d\xe9crite dans ce chapitre est de la photographie computationnelle."}),"\n",(0,a.jsx)(r.mermaid,{value:'graph TD\n    subgraph "Diagramme de Venn de la photographie computationnelle"\n        A["Optique<br/>Objectifs, Ouverture, OIS"]\n        B["Capteurs<br/>CMOS, Bayer, Obturateur roulant"]\n        C["Apprentissage automatique<br/>Segmentation, D\xe9bruitage, Profondeur"]\n        D["Traitement signal multi-images<br/>Fusion HDR, Fusion nuit, EIS"]\n    end\n    A -- Chevauchement --\x3e E["Bokeh portrait"]\n    B -- Chevauchement --\x3e F["Capture HDR bracket\xe9e"]\n    C -- Chevauchement --\x3e G["Segmentation portrait ML"]\n    D -- Chevauchement --\x3e H["Fusion temporelle Night Sight"]\n    A & B & C & D --\x3e I["Zoom multi-cam\xe9ra fluide"]'}),"\n",(0,a.jsx)(r.p,{children:"C'est l'id\xe9e la plus importante \xe0 retenir pour les chapitres sur l'API Camera2 qui suivent. L'API Camera2 n'est pas seulement un outil pour \"prendre une photo\". C'est une interface de contr\xf4le de bas niveau qui permet \xe0 votre application de d\xe9clencher des rafales multi-images pr\xe9cises, de lire les m\xe9tadonn\xe9es du gyroscope par image, de s\xe9lectionner quelle cam\xe9ra physique se d\xe9clenche \xe0 quel rapport de zoom et de faire passer des images par des r\xe9seaux neuronaux sur l'appareil \u2014 les briques de base pour impl\xe9menter vos propres fonctionnalit\xe9s de photographie computationnelle."}),"\n",(0,a.jsx)(r.h2,{id:"r\xe9sum\xe9",children:"R\xe9sum\xe9"}),"\n",(0,a.jsx)(r.p,{children:"Dans ce chapitre, vous avez appris les algorithmes r\xe9els derri\xe8re les fonctionnalit\xe9s de la photographie moderne sur smartphone. Le HDR utilise le bracketing d'exposition sur 3 \xe0 10 images, l'alignement bas\xe9 sur les caract\xe9ristiques par image et le mappage de tons pour capturer une plage dynamique que le capteur ne peut pas voir en une seule exposition. Le mode portrait calcule une carte de profondeur par pixel via la disparit\xe9 de la cam\xe9ra st\xe9r\xe9o, la t\xe9l\xe9m\xe9trie laser ToF ou l'estimation de la profondeur ML monoculaire, puis ex\xe9cute une segmentation du sujet U-Net et applique un flou gaussien variable par pixel mis \xe0 l'\xe9chelle par la profondeur. Le mode nuit capture 8 \xe0 15 expositions courtes, les aligne \xe0 l'aide de l'EIS assist\xe9 par gyro, applique une fusion temporelle robuste des pixels pour r\xe9duire le bruit de 3,5\xd7 et effectue un mappage de tons local du r\xe9sultat. La vid\xe9o au ralenti \xe0 960 fps doit recadrer le capteur car la bande passante de lecture MIPI est le goulot d'\xe9tranglement mat\xe9riel. Les photos ultra-grand-angle subissent une correction de distorsion g\xe9om\xe9trique, une correction d'aberration chromatique et une correction d'ombrage des coins dans l'ISP avant de devenir visualisables. Les cam\xe9ras t\xe9l\xe9objectifs p\xe9riscopes utilisent un prisme \xe0 45\xb0 pour plier le chemin de la lumi\xe8re \xe0 90\xb0 et faire tenir un objectif optique 10\xd7 \xe0 l'int\xe9rieur d'un t\xe9l\xe9phone de 8,5 mm d'\xe9paisseur. Vous avez appris la d\xe9finition de la photographie computationnelle : la fusion de l'optique, des capteurs, de l'apprentissage automatique et du traitement du signal multi-images pour cr\xe9er des images hors de port\xe9e de tout syst\xe8me objectif/capteur unique."}),"\n",(0,a.jsx)(r.h2,{id:"et-ensuite-",children:"Et ensuite ?"}),"\n",(0,a.jsxs)(r.p,{children:["Le chapitre 4 est le chapitre pratique. Vous installerez l'application compagnon ",(0,a.jsx)(r.strong,{children:"Android Camera Parameters"})," \xe0 partir des sources ou de Google Play, la lancerez sur votre propre t\xe9l\xe9phone et inspecterez exactement ce dont votre mat\xe9riel est capable. Vous apprendrez \xe0 lire les ID de cam\xe9ra et les directions de face, \xe0 v\xe9rifier le niveau mat\xe9riel de chaque cam\xe9ra (LEGACY / LIMITED / FULL / LEVEL_3), \xe0 \xe9num\xe9rer les formats de sortie pris en charge (JPEG, YUV_420_888, PRIVATE, RAW_SENSOR, JPEG_R Ultra HDR), \xe0 trouver les plages de FPS maximales pour le ralenti, \xe0 explorer les rapports de zoom et les points de basculement entre les cam\xe9ras physiques de votre t\xe9l\xe9phone, et \xe0 v\xe9rifier si votre capteur principal prend en charge la capture RAW \u2014 en notant les r\xe9ponses pour votre appareil sp\xe9cifique, car ces r\xe9ponses d\xe9terminent ce qui est possible ou non pour votre propre application API Camera2 sur ce t\xe9l\xe9phone."]})]})}function p(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,a.jsx)(r,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,r,n){n.d(r,{R:()=>i,x:()=>o});var t=n(6540);const a={},s=t.createContext(a);function i(e){const r=t.useContext(s);return t.useMemo(function(){return"function"==typeof e?e(r):{...r,...e}},[r,e])}function o(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),t.createElement(s.Provider,{value:r},e.children)}}}]);